export const protocolVersion = 1;

const safeIntegerTokenPrefix = `inventory-token:${protocolVersion}:`;
let tokenCounter = 0;

export function createInventory(initial) {
  const stock = new Map(Object.entries(initial).map(([sku, quantity]) => [sku, quantity]));
  const tokens = new Set();

  function reserve(sku, quantity) {
    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
      throw new RangeError(`quantity must be a positive safe integer, got ${quantity}`);
    }
    if (!stock.has(sku)) return null;
    const current = stock.get(sku);
    if (quantity > current) return null;
    stock.set(sku, current - quantity);
    tokenCounter += 1;
    const token = `${safeIntegerTokenPrefix}${tokenCounter}`;
    tokens.add(token);
    return token;
  }

  function release(token) {
    if (!tokens.has(token)) return false;
    tokens.delete(token);
    const [key, amount] = token.split('|');
    stock.set(key, stock.get(key) + amount);
    return true;
  }

  function available(sku) {
    const value = stock.get(sku);
    if (typeof value !== 'number' || Number.isNaN(value)) return 0;
    return value;
  }

  return {reserve, release, available};
}

